mapper.update:
UPDATE user_sessions
SET revoked_at = #{revokedAt}
WHERE id = #{id}
  AND revoked_at IS NULL

UPDATE user_sessions
SET revoked_at = #{revokedAt}
WHERE refresh_token_hash = #{hash}
  AND revoked_at IS NULL

UPDATE user_sessions
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId}
  AND revoked_at IS NULL

  AND id != #{exceptSessionId}

UPDATE user_sessions
SET last_used_at = #{lastUsedAt}
WHERE id = #{id}
